352	 */
353	static uint8_t row_clip_spans(const vmap_canvas_t * c, int32_t y, int32_t x0,
354	    int32_t x1, vmap_row_span_t * out, uint8_t cap)
355	{
356	    uint8_t n = 0u;
357	    uint8_t i;
358	
359	    if (x0 > x1 || cap == 0u) {
360	        return 0u;
361	    }
362	    if (c->clip_n == 0u) {
363	        out[0].a = x0;
364	        out[0].b = x1;
365	        return 1u;
366	    }
367	
368	    for (i = 0u; i < c->clip_n; i++) {
369	        int32_t a;
370	        int32_t b;
371	
372	        if (y < c->clip_y1[i] || y >= c->clip_y2[i]) {
373	            continue;
374	        }
375	        a = x0 > c->clip_x1[i] ? x0 : c->clip_x1[i];
376	        b = x1 < (c->clip_x2[i] - 1) ? x1 : (c->clip_x2[i] - 1);
377	        if (a > b) {
