385	/** @brief 把 [x0,x1]（闭区间）填成 color；成对 32 位写。 */
386	static void fill_run_u16(uint16_t * row, int32_t x0, int32_t x1, uint16_t color)
387	{
388	    const uint32_t pair = ((uint32_t)color << 16) | (uint32_t)color;
389	    int32_t x = x0;
390	
391	    if (!row || x0 > x1) {
392	        return;
393	    }
394	
395	    /* 对齐按**地址**判，不能按下标判：vmap_render_scroll 会把 row 本身偏移
396	     * dx 再交给本函数，指针可能落在奇数元素上。
397	     *
398	     * 只做成对（32 位）写就停在这里 —— 不再上 32 字节块：上板实测
399	     * `[vperf] psram ... blk/w=100%`，即块写与逐字写的**周期/字节完全一样**
400	     * （都是 ~22 周期/字节），写通路不合并，块写只省指令不省访问。
401	     * 详见 docs/map/perf/MEASUREMENTS.md §2.5。 */
402	    if (((uintptr_t)(row + x) & 3u) != 0u) {
403	        row[x++] = color;
404	        STAT_STORE(2);
405	    }
406	    {
407	        const int32_t npair = (x1 - x + 1) / 2;
408	
409	        if (npair > 0) {
410	            int32_t n = npair;
411	
412	            while (n-- > 0) {
413	                *(uint32_t *)(void *)(row + x) = pair;
414	                x += 2;
415	            }
416	            STAT_STORE_N(npair, npair * 4);
417	        }
418	    }
419	    if (x <= x1) {
420	        row[x] = color;
421	        STAT_STORE(2);
422	    }
423	}
