460	/* ——— 多边形扫描填充：逐行增量推进 —————————————————————————————
461	 *
462	 * 旧写法每个扫描行、每条活动边都算一次
463	 *
464	 *     x = xi + trunc((y_scan - yi) * dx / dy)
465	 *
466	 * 这里的 `(int64)/(int64)` 在这颗 M33 上没有硬件指令，走 `__aeabi_ldivmod`
467	 * （一次 150~300 周期），而多边形填充的内层就是**行数 × 活动边数**
468	 * （实测一帧 23120 次，见 `[vperf] prim cross=`）—— 是这条路上最大的单笔开销。
469	 *
470	 * 增量写法：每行 y_scan 只涨一个常量，分子每行只加一个常量 step。难点是必须
471	 * **逐位**复现 C 的**向零截断**除法：负数余数的符号与 floor 不同，而"每行加一个
472	 * 常量"对截断除法并不封闭 —— 只维护 `|余数| < |dy|` 会让商漂一位（余数的符号
473	 * 约定也是解的一部分，光靠"补一次 ±1"补不回来）。所以这里换成**全非负**的
474	 * "面积 + floor"形式：
475	 *
476	 *   M   = |dy|                                     > 0
477	 *   sgn = sign(dx)                                 （商的方向；dx == 0 时取 +1）
478	 *   P_k = |dx| * |y_scan_k - yi|                   ≥ 0，每行只加常量 G
479	 *   A_k = floor(P_k / M)，a_k = P_k - A_k * M      （0 ≤ a_k < M）
480	 *   x_k = xi + sgn * A_k                           （= 原式，见下）
481	 *
482	 * 于是每行的推进只剩：
483	 *
484	 *     a += gr;  if (a >= M) { a -= M; x += sgn; }  x += gm;
485	 *
486	 * （`gm = sgn*floor(G/M)`、`gr = G mod M` 在装配时算一次 —— 一次除法每条边而已。）
487	 * 一次加法、一次比较、最多一次 ±1，没有乘法、没有除法、也没有会累积误差的
488	 * 定点斜率：维护的是 floor 分解的恒等式本身。
489	 *
490	 * 为什么 `x_k = xi + sgn*A_k` 就是原式：活动窗口里 `y_scan - yi` 的符号是固定的
491	 * （dy > 0 时 ∈ [0, dy)，dy < 0 时 ∈ (dy, 0]），所以 n = (y_scan-yi)*dx 的符号也
492	 * 固定，等于 sgn*sign(dy)；于是 trunc(n/dy) 就等于"按 |dy| 取 floor 再补符号"。
493	 *
494	 * 首行（每条边只此一次）仍按上面的定义直接算，等价于原式的量。
495	 * 量级：画布局部坐标 ±1000 px ⇒ |dx| ≤ 512000 fp ⇒ P ≤ 2.6e11（int64，除法只有
496	 * 这一处）、A ≤ |dx| ≤ 512000（int32），都装得下。
497	 */
498	/** 逐行维护状态的边数上限；**下标 ≥ 上限的边照旧逐行算**（像素不变，只是继续吃
499	 *  那一次软除）。放 .bss 不放栈：实测 `bicycle_ui` 栈只剩 ~10 KB 余量，而按边的
500	 *  下标开数组要能被 n 覆盖 —— 静态数组的代价是 RAM，栈的代价是崩溃。
501	 *
502	 *  ⚠ 别改成"槽号 = i & (N-1)"那种取模复用：看着省内存，实测**反而更慢** ——
503	 *  大的面要素（n 上百、同时激活的边一二十条）下标相差 64 的整数倍会有多对撞在
504	 *  同一个槽上，于是每行都要重新装配 + 播种（两次除法）⇒ `poly` 段实测 +13%。
505	 *  撞车只有在**同时激活**的边之间才会发生，而大面要素恰恰是这个条件最容易满足的。 */
506	#define VMAP_POLY_DDA_CAP 256
507	
508	typedef struct {
509	    uint32_t gen;   /**< 装配时那次调用的代号（静态数组的残留必须能认出来） */
510	    int32_t x;      /**< 当前扫描行的 x（fp 或整像素，量纲由调用者定） */
511	    int32_t a;      /**< P mod M，恒在 [0, M) */
512	    int32_t gr;     /**< G mod M，恒在 [0, M) */
513	    int32_t gm;     /**< sgn * floor(G / M)：每行 x 的常量增量 */
514	    int32_t sgn;    /**< sign(dx)：商的方向（±1） */
515	} vmap_poly_dda_t;
516	
517	/** 槽号 == 边号；`gen` 用来区分"这一槽是不是本次调用装配的"（0 是 .bss 初值）。 */
518	static vmap_poly_dda_t s_poly_dda[VMAP_POLY_DDA_CAP];
519	static uint32_t s_poly_dda_gen;
520	
521	/**
522	 * @brief 装配一条边的常量部分：每行推进用的 gm / gr 与符号。
523	 * @param step 每行分子的增量：fp 路径是 `VMAP_FP_ONE * dx`，整像素路径是 `dx`。
524	 * @param yi   边的起点 y；`yj - yi` 必须非 0（调用点已用 live 判据保证）。
525	 */
526	static void vmap_poly_dda_arm(vmap_poly_dda_t * e, int32_t yi, int32_t yj,
527	    int64_t step)
528	{
529	    const int32_t dy = yj - yi;
530	
531	    e->gen = s_poly_dda_gen;
532	    e->a = 0;
533	    e->gr = 0;
534	    e->gm = 0;
535	    e->sgn = (step < 0) ? -1 : 1;       /* sign(dx)：step 与 dx 同号 */
536	    if (dy != 0) {
537	        const int64_t m = (dy < 0) ? -(int64_t)dy : (int64_t)dy;
538	        const int64_t g = (int64_t)e->sgn * ((dy > 0) ? 1 : -1) * step;
539	        /* 商与余数都要（= 截断除法的两半）。⚠ 本工具链**不合并**这两个
540	         * libcall：`g/m` 与 `g%m` 各调一次 __aeabi_ldivmod（写成 `g - q*m`
541	         * 也一样，会被规范化回 `%`）。所以这里每条边是 2 次软除 —— 但只在
542	         * **被激活那一次**发生（一帧 ~1.5~3k 次），可以忽略。 */
543	        int64_t q = g / m;
544	        int64_t r = g % m;
545	
546	        if (r < 0) {                    /* 归一到 floor：0 ≤ r < m */
547	            r += m;
548	            q -= 1;
549	        }
550	        e->gm = (int32_t)((int64_t)e->sgn * q);
551	        e->gr = (int32_t)r;
552	    }
553	}
554	
555	/**
556	 * @brief 按定义算这条边在当前扫描行上的 x（`A = floor(|dx|*|delta_y| / |dy|)`）。
557	 * @param x_base   xi（fp / 整像素路径）或 `xi * VMAP_FP_ONE`（AA 路径的定标）
558	 * @param dx       `xj - xi`，**已按调用者的量纲定标**（AA 路径传 `dx * 256`）
559	 *
560	 * 与原式逐位相同；一条边只在**被激活那一次**走这里，所以这一次 64 位除法不算什么。
561	 */
562	static inline void vmap_poly_dda_seed(vmap_poly_dda_t * e, int64_t x_base,
563	    int64_t dx, int32_t dy, int32_t delta_y)
564	{
565	    const int64_t m = (dy < 0) ? -(int64_t)dy : (int64_t)dy;
566	    const int64_t area = ((dx < 0) ? -dx : dx)
567	        * ((delta_y < 0) ? -(int64_t)delta_y : (int64_t)delta_y);
568	    const int64_t q = area / m;         /* 两者都非负 ⇒ 截断即 floor */
569	
570	    e->x = (int32_t)(x_base + (int64_t)e->sgn * q);
571	    e->a = (int32_t)(area - q * m);     /* < m，见 arm 的量级说明 */
572	}
573	
574	/** @brief 推进一行（m == |dy| ≥ 1）。 */
575	static inline void vmap_poly_dda_step(vmap_poly_dda_t * e, int32_t m)
576	{
577	    const int32_t a = e->a + e->gr;
578	
579	    e->x += e->gm;
580	    if (a >= m) {
581	        e->a = a - m;
582	        e->x += e->sgn;
583	    } else {
584	        e->a = a;
585	    }
586	}
587	
588	/** @brief 这条边在当前扫描行是否激活（与改动前的双条件逐字相同）。 */
589	static inline bool vmap_poly_dda_live(int32_t yi, int32_t yj, int32_t y_scan)
590	{
591	    return (yi <= y_scan && yj > y_scan) || (yj <= y_scan && yi > y_scan);
592	}
