594	#if VMAP_RENDER_AA
595	static uint16_t mix_rgb565(uint16_t bg, uint16_t fg, uint8_t mix)
596	{
597	    uint32_t mix5;
598	    uint32_t bg32;
599	    uint32_t fg32;
600	    uint32_t r;
601	    uint32_t g;
602	    uint32_t b;
603	
604	    if (mix >= 255) {
605	        return fg;
606	    }
607	    if (mix == 0) {
608	        return bg;
609	    }
610	
611	    mix5 = ((uint32_t)mix + 4U) >> 3;
612	    bg32 = bg;
613	    fg32 = fg;
614	    r = ((bg32 & 0xF800U) + (((fg32 & 0xF800U) - (bg32 & 0xF800U)) * mix5 >> 5))
615	        & 0xF800U;
616	    g = ((bg32 & 0x07E0U) + (((fg32 & 0x07E0U) - (bg32 & 0x07E0U)) * mix5 >> 5))
617	        & 0x07E0U;
618	    b = ((bg32 & 0x001FU) + (((fg32 & 0x001FU) - (bg32 & 0x001FU)) * mix5 >> 5))
619	        & 0x001FU;
620	    return (uint16_t)(r | g | b);
621	}
