656	/** @brief 单像素混合（边界与裁剪已在调用方处理完毕）。 */
657	static inline void blend_row_pixel(uint16_t * row, int32_t x, uint16_t color,
658	    uint8_t alpha)
659	{
660	    if (alpha == 0u) {
661	        return;
662	    }
663	    if (alpha >= 255u) {
664	        row[x] = color;
665	        STAT_STORE(2);
666	        return;
667	    }
668	    row[x] = mix_rgb565(row[x], color, alpha);
669	    STAT_STORE(2);
670	}
