698	static void blend_pixel(vmap_canvas_t * c, int32_t x, int32_t y, uint16_t color,
699	    uint8_t alpha)
700	{
701	    uint16_t * row;
702	
703	    if (!c || !c->buf || alpha == 0) {
704	        return;
705	    }
706	    if ((uint32_t)x >= (uint32_t)c->w || (uint32_t)y >= (uint32_t)c->h) {
707	        return;
708	    }
709	    if (!canvas_in_clip(c, x, y)) {
710	        return;
711	    }
712	    if (alpha >= 255) {
713	        put_pixel(c, x, y, color);
714	        return;
715	    }
716	
717	    row = (uint16_t *)((uint8_t *)c->buf + (size_t)y * c->stride);
718	    row[x] = mix_rgb565(row[x], color, alpha);
