726	static void cover_span_fp(vmap_canvas_t * c, int32_t y, int32_t x0_fp,
727	    int32_t x1_fp, uint16_t color)
728	{
729	    vmap_row_span_t sp[VMAP_RENDER_DIRTY_MAX];
730	    uint16_t * row;
731	    int32_t xa;
732	    int32_t xb;
733	    int32_t f_lo;
734	    int32_t f_hi;
735	    uint8_t ns;
736	    uint8_t s;
737	
738	    if (!c || !c->buf || (uint32_t)y >= (uint32_t)c->h) {
739	        return;
740	    }
741	    if (x0_fp > x1_fp) {
742	        int32_t t = x0_fp;
743	        x0_fp = x1_fp;
744	        x1_fp = t;
745	    }
746	
747	    xa = x0_fp >> VMAP_FP_SHIFT;
748	    xb = (x1_fp + VMAP_FP_ONE - 1) >> VMAP_FP_SHIFT;
749	    if (xa < 0) {
750	        xa = 0;
751	    }
752	    if (xb > c->w - 1) {
753	        xb = c->w - 1;
754	    }
755	    if (xa > xb) {
756	        return;
757	    }
758	
759	    ns = row_clip_spans(c, y, xa, xb, sp, VMAP_RENDER_DIRTY_MAX);
760	    if (ns == 0u) {
761	        return;
762	    }
763	
764	    row = (uint16_t *)((uint8_t *)c->buf + (size_t)y * c->stride);
765	
766	    /* 被整个像素覆盖的那一段用成对写；两端最多各一个部分覆盖像素走逐像素
767	     * 覆盖度。三段的并集与旧实现的"逐像素 cov>=1 就落笔"完全相同。 */
768	    f_lo = (x0_fp + VMAP_FP_ONE - 1) >> VMAP_FP_SHIFT;
769	    f_hi = (x1_fp - VMAP_FP_ONE) >> VMAP_FP_SHIFT;
770	
771	    for (s = 0u; s < ns; s++) {
772	        const int32_t a = sp[s].a;
773	        const int32_t b = sp[s].b;
774	        int32_t r1 = f_lo > a ? f_lo : a;   /* 第一个被整像素覆盖的 x */
775	        int32_t r2 = f_hi < b ? f_hi : b;   /* 最后一个被整像素覆盖的 x */
776	
777	        if (r1 > r2) {
778	            /* 整条跨度还不足一个像素：此时两端其实是同一个（或相邻）像素，
779	             * 必须当成**一段**处理，否则中间那个像素会被混合两次。 */
780	            cover_partial_px(row, a, b, x0_fp, x1_fp, color);
781	            continue;
782	        }
783	        cover_partial_px(row, a, r1 - 1, x0_fp, x1_fp, color);
784	        fill_run_u16(row, r1, r2, color);
785	        cover_partial_px(row, r2 + 1, b, x0_fp, x1_fp, color);
786	    }
787	}
