789	static void fill_polygon_fp(vmap_canvas_t * c, const vmap_fp_point_t * pts,
790	    int32_t n, uint16_t color)
791	{
792	    const uint32_t gen = ++s_poly_dda_gen;
793	    int32_t min_y;
794	    int32_t max_y;
795	    int32_t y;
796	    VMAP_PRIM_T0();
797	    int32_t _prim_xc = 0;
798	
799	    if (n < 3) {
800	        return;
801	    }
802	    vmap_prim_init();
803	    _prim_t0 = vmap_prim_cyc();
804	
805	    min_y = pts[0].y >> VMAP_FP_SHIFT;
806	    max_y = pts[0].y >> VMAP_FP_SHIFT;
807	    for (int32_t i = 1; i < n; i++) {
808	        int32_t py = pts[i].y >> VMAP_FP_SHIFT;
809	        if (py < min_y) {

809	        if (py < min_y) {
810	            min_y = py;
811	        }
812	        if (py > max_y) {
813	            max_y = py;
814	        }
815	    }
816	    if (min_y < 0) {
817	        min_y = 0;
818	    }
819	    if (max_y > c->h - 1) {
820	        max_y = c->h - 1;
821	    }
822	
823	    for (y = min_y; y <= max_y; y++) {
824	        int32_t xs_fp[64];
825	        int32_t cnt = 0;
826	        const int32_t y_scan_fp = (y << VMAP_FP_SHIFT) + (VMAP_FP_ONE / 2);
827	
828	        for (int32_t i = 0; i < n; i++) {
829	            const int32_t j = (i == 0) ? (n - 1) : (i - 1);
830	            const int32_t yi_fp = pts[i].y;
831	            const int32_t yj_fp = pts[j].y;
832	            int32_t x_fp;
833	
834	            if (!vmap_poly_dda_live(yi_fp, yj_fp, y_scan_fp)) {
835	                continue;
836	            }
837	            if (i < VMAP_POLY_DDA_CAP) {
838	                vmap_poly_dda_t * e = &s_poly_dda[i];
839	
840	                if (e->gen != gen) {
841	                    const int32_t dx = pts[j].x - pts[i].x;
842	
843	                    vmap_poly_dda_arm(e, yi_fp, yj_fp,
844	                        (int64_t)VMAP_FP_ONE * dx);
845	                    vmap_poly_dda_seed(e, pts[i].x, dx, yj_fp - yi_fp,
846	                        y_scan_fp - yi_fp);
847	                } else {
848	                    vmap_poly_dda_step(e, (yj_fp > yi_fp) ? (yj_fp - yi_fp)
849	                        : (yi_fp - yj_fp));
850	                }
851	                x_fp = e->x;
852	            } else {
853	                /* 超过上限的边：照旧按原式逐行算（像素不变） */
854	                x_fp = (int32_t)((int64_t)(y_scan_fp - yi_fp)
855	                    * (pts[j].x - pts[i].x) / (yj_fp - yi_fp) + pts[i].x);
856	            }
857	
858	            _prim_xc++;
859	            if (cnt < (int32_t)(sizeof(xs_fp) / sizeof(xs_fp[0]))) {
860	                xs_fp[cnt++] = x_fp;
861	            }
862	        }
863	
864	        for (int32_t a = 1; a < cnt; a++) {
865	            int32_t v = xs_fp[a];
866	            int32_t b = a - 1;
867	
868	            while (b >= 0 && xs_fp[b] > v) {
869	                xs_fp[b + 1] = xs_fp[b];
870	                b--;
871	            }
872	            xs_fp[b + 1] = v;
873	        }
874	        for (int32_t a = 0; a + 1 < cnt; a += 2) {
875	            cover_span_fp(c, y, xs_fp[a], xs_fp[a + 1], color);
876	        }
877	    }
878	
879	    s_prim_poly_fp += vmap_prim_cyc() - _prim_t0;
880	    s_prim_n_poly_fp++;
881	    s_prim_cross += (uint32_t)_prim_xc;
882	    s_prim_scan += (uint32_t)(n * ((max_y >= min_y) ? (max_y - min_y + 1) : 0));
883	    vmap_prim_note(n, vmap_prim_cyc() - _prim_t0);
884	}
