925	/** @brief 行 y 的中点相对圆心的 dy（fp）。 */
926	static inline int32_t disc_dy_fp(int32_t y, int32_t cy_fp)
927	{
928	    return (y << VMAP_FP_SHIFT) + (VMAP_FP_ONE / 2) - cy_fp;
929	}
