931	/** @brief 把 dx 收缩到满足 dx² <= v 的最大整数（v = outer2 - dy²）。 */
932	static inline int32_t disc_shrink_dx(int32_t dx, int64_t v)
933	{
934	    while (dx > 0 && (int64_t)dx * (int64_t)dx > v) {
935	        dx--;
936	    }
937	    return dx;
938	}
