940	static void fill_disc_aa_fp(vmap_canvas_t * c, int32_t cx_fp, int32_t cy_fp,
941	    int32_t r_fp, uint16_t color)
942	{
943	    const int64_t outer2 = (int64_t)r_fp * (int64_t)r_fp;
944	    int32_t y0;
945	    int32_t y1;
946	    int32_t yc;
947	    int32_t dx0;
948	    int32_t dx;
949	    int64_t v;
950	    int32_t y;
951	    VMAP_PRIM_T0();
952	
953	    if (r_fp < VMAP_FP_ONE / 4) {
954	        blend_pixel(c, cx_fp >> VMAP_FP_SHIFT, cy_fp >> VMAP_FP_SHIFT, color, 255);
955	        return;
956	    }
957	    vmap_prim_init();
958	    _prim_t0 = vmap_prim_cyc();
959	
960	    y0 = (cy_fp - r_fp) >> VMAP_FP_SHIFT;
961	    y1 = (cy_fp + r_fp + VMAP_FP_ONE - 1) >> VMAP_FP_SHIFT;
962	    if (y0 < 0) {
963	        y0 = 0;
964	    }
965	    if (y1 > c->h - 1) {
966	        y1 = c->h - 1;
967	    }
968	    if (y0 > y1) {
969	        return;
970	    }
971	
972	    /*
973	     * 行半宽 dx(y) = floor(sqrt(outer2 - dy²)) 从"离真圆心最近的那一行"向两侧
974	     * 单调不增。所以只有那一行需要一次真 sqrt，其余行各自单调递减逼近即可：
975	     * v 是整数、double 尾数足够精确 ⇒ 原式截断就等于精确的 floor(sqrt(v))，
976	     * 于是结果**逐位相同**，但把每行一次**软双精度 sqrt** 全去掉了。
977	     * draw_road_polyline() 在每个折线顶点都画一个圆盘，这里正是它的热点。
978	     *
979	     * 起点必须取「最近的一行」（cy_fp >> 8）而不是 (cy_fp-128) >> 8：
980	     * 后者会落在真圆心下方一行，可能出现"起点半宽 < 下一行半宽"，
981	     * 那样单调逼近就会给出偏小的宽度。
982	     */
983	    yc = cy_fp >> VMAP_FP_SHIFT;
984	    if (yc < y0) {
985	        yc = y0;
986	    }
987	    if (yc > y1) {
988	        yc = y1;
989	    }
990	
991	    v = outer2 - (int64_t)disc_dy_fp(yc, cy_fp) * disc_dy_fp(yc, cy_fp);
992	    if (v < 0) {
993	        return;                        /* 连最宽的一行都不覆盖 ⇒ 无像素 */
994	    }
995	    dx0 = (int32_t)sqrt((double)v);
996	
997	    dx = dx0;
998	    for (y = yc; y <= y1; y++) {
999	        v = outer2 - (int64_t)disc_dy_fp(y, cy_fp) * disc_dy_fp(y, cy_fp);
1000	        if (v < 0) {
1001	            break;
1002	        }
1003	        dx = disc_shrink_dx(dx, v);
1004	        cover_span_fp(c, y, cx_fp - dx, cx_fp + dx, color);
1005	    }
1006	
1007	    dx = dx0;                          /* 另一侧从圆心行的宽度重新起算 */
1008	    for (y = yc - 1; y >= y0; y--) {
1009	        v = outer2 - (int64_t)disc_dy_fp(y, cy_fp) * disc_dy_fp(y, cy_fp);
1010	        if (v < 0) {
1011	            break;
1012	        }
1013	        dx = disc_shrink_dx(dx, v);
1014	        cover_span_fp(c, y, cx_fp - dx, cx_fp + dx, color);
1015	    }
1016	
1017	    s_prim_disc += vmap_prim_cyc() - _prim_t0;
1018	    s_prim_n_disc++;
1019	}
