3064	/*
3065	 * 这里原有一个 `render_fill_span(row, x0, x1, color)`（成对写的一行填充）。
3066	 * scroll 改成"矩形 + 两条边"之后它没有调用者了 —— 补边现在走
3067	 * `vmap_blit_fill()`，CPU 那支的成对写等价物在 `vmap_blit.c` 的 `cpu_fill()`。
3068	 */
3069	
3070	void vmap_render_scroll(vmap_canvas_t * c, int32_t dx, int32_t dy, uint16_t fill)
3071	{
3072	    vmap_blit_surface_t surf;
3073	    vmap_blit_t * blit;
3074	    int32_t copy_w;
3075	    int32_t copy_h;
3076	    int32_t x0;
3077	    int32_t y0;
3078	
3079	    if (!c || !c->buf) {
3080	        return;
3081	    }
3082	
3083	    if (dx == 0 && dy == 0) {
3084	        return;
3085	    }
3086	
3087	    if (dx >= c->w || dx <= -c->w || dy >= c->h || dy <= -c->h) {
3088	        vmap_render_clear(c, fill);
3089	        return;
3090	    }
3091	
3092	    /*
3093	     * 原来这条是逐行 memmove + 逐行补边；现在拆成**一块矩形 + 两条边**，
3094	     * 这样整块矩形才有机会落到 EPIC 上（一条命令 vs 472 次函数调用）。
