#include "myvendor_epic_blit.h"

struct vmap_blit_s {
    vmap_blit_backend_t backend;
    /**
     * 自检结论：**同一块缓冲内源/目的重叠**的搬运，在各方向上是否与 CPU
     * 逐位一致。下标 = [平移 dx 的符号 + 1][平移 dy 的符号 + 1]（2 = 正、1 = 0、
     * 0 = 负），true = 该方向可信。全 false（自检没跑成）⇒ 重叠一律退回 CPU。
     */
