1674	/**
1675	 * @brief 半圆端帽：从 c+hw·u 扫过 c+hw·rot(u,-90°) 到 c-hw·u，半径 hw。
1676	 *
1677	 * 只写中间的 k=1..segs-1 个点（起点是左偏置末点、终点是右偏置末点，已有多边形
1678	 * 顶点），因此不会出现重复顶点。`u` 是单位法线；`rot(u,-90°) = (uy,-ux)` 正好是
1679	 * 路径前进方向，所以端帽总是从端点向外鼓。
1680	 *
1681	 * @return 写入后的点数。
1682	 */
1683	static int32_t ribbon_cap_emit(vmap_fp_point_t * poly, int32_t pn, int32_t cap,
1684	    int32_t cx, int32_t cy, double hw, double ux, double uy, int32_t segs)
