1687	     * Q15 后与 cos/sin 表组合，不再有 double 逐点运算（板端 double 是软浮点）。 */
1688	    const int32_t cx_fp = cx * VMAP_FP_ONE;
1689	    const int32_t cy_fp = cy * VMAP_FP_ONE;
1690	    const int32_t r_fp = (int32_t)lround(hw * (double)VMAP_FP_ONE);
1691	    const int32_t ux15 = (int32_t)lround(ux * 32768.0);
1692	    const int32_t uy15 = (int32_t)lround(uy * 32768.0);
1693	    const int32_t step = 16 / segs;
1694	    int32_t k;
1695	
1696	    for (k = step; k < 16; k += step) {
1697	        const int64_t c = s_ribbon_cos16[k];
1698	        const int64_t s = s_ribbon_sin16[k];
1699	        /* rot(u,-90°) = (uy,-ux)：点 = c·u + s·rot(u,-90°) */
1700	        const int32_t ox = (int32_t)((c * ux15 + s * uy15) >> 15);
1701	        const int32_t oy = (int32_t)((c * uy15 - s * ux15) >> 15);
1702	
1703	        if (pn >= cap) {
1704	            break;
1705	        }
1706	        poly[pn].x = cx_fp + (int32_t)(((int64_t)r_fp * ox) >> 15);
1707	        poly[pn].y = cy_fp + (int32_t)(((int64_t)r_fp * oy) >> 15);
