427	/**
428	 * @brief 旋转自检：用"像素里编码自己坐标"的图案转一次，抽查若干目的点。
429	 *
430	 * @details 判据是**坐标**而不是颜色：源 32x32 每像素写 (x<<11)|(y<<5)，
431	 *          转 30° 后对抽查点做逆变换求源点，读回来的坐标必须落在 ±2 px 内
432	 *          （EPIC 最近邻 + 亚像素）。失败时把第一处"期望 vs 实际"打出来 ——
433	 *          角度正负、pivot 语义错了都能从那一行反推。
434	 */
435	bool myvendor_epic_rotate_selftest(void)
436	{
437	  enum
438	  {
439	    SRC_W = 32, SRC_H = 32, DST_W = 48, DST_H = 48, PIV = 16, ANGLE = 300,
440	    PROBES = 10
441	  };
442	  static uint16_t src[SRC_W * SRC_H];
443	  static uint16_t dst[DST_W * DST_H];
444	  static const int16_t probe[PROBES][2] =
445	  {
446	    { 24, 24 }, { 24, 12 }, { 24, 36 }, { 12, 24 }, { 36, 24 },
447	    { 16, 16 }, { 32, 32 }, { 32, 16 }, { 16, 32 }, { 24, 6 }
448	  };
449	  const int32_t cx = DST_W / 2;
450	  const int32_t cy = DST_H / 2;
451	  const double th = (double)ANGLE * 0.1 * M_PI / 180.0;
452	  int32_t x;
453	  int32_t y;
454	  int32_t i;
455	  int32_t fails = 0;
456	
457	  for (y = 0; y < SRC_H; y++)
458	    {
459	      for (x = 0; x < SRC_W; x++)
460	        {
461	          src[y * SRC_W + x] = (uint16_t)(((uint16_t)x << 11)
462	            | ((uint16_t)y << 5));
463	        }
464	    }
465	  memset(dst, 0, sizeof(dst));
466	
467	  if (!myvendor_epic_rotate(src, SRC_W * sizeof(uint16_t), SRC_W, SRC_H,
468	          dst, DST_W * sizeof(uint16_t), DST_W, DST_H, ANGLE, PIV, PIV,
469	          cx, cy))
470	    {
471	      syslog(LOG_WARNING, "[vrot] selftest SKIP: epic rotate unavailable");
472	      return false;
473	    }
474	
475	  for (i = 0; i < PROBES; i++)
476	    {
477	      /* 目的 (u,v) → 源：s = piv + R(-θ)·((u,v) - c)，θ 顺时针（y 向下）。 */
478	      const double du = (double)(probe[i][0] - cx);
479	      const double dv = (double)(probe[i][1] - cy);
480	      const double sx = (double)PIV + (cos(th) * du + sin(th) * dv);
481	      const double sy = (double)PIV + (-sin(th) * du + cos(th) * dv);
482	      const int32_t rx = (int32_t)lround(sx);
483	      const int32_t ry = (int32_t)lround(sy);
484	      uint16_t got;
485	      int32_t gx;
486	      int32_t gy;
487	
488	      if (rx < 0 || ry < 0 || rx >= SRC_W || ry >= SRC_H)
489	        {
490	          continue;                /* 该点落在源的空白区 */
491	        }
492	
493	      got = dst[probe[i][1] * DST_W + probe[i][0]];
494	      gx = (int32_t)((got >> 11) & 0x1F);
495	      gy = (int32_t)((got >> 5) & 0x3F);
496	
497	      if (abs((int)(gx - rx)) > 2 || abs((int)(gy - ry)) > 2)
498	        {
499	          if (fails == 0)
500	            {
501	              syslog(LOG_WARNING,
502	                "[vrot] selftest fail dst(%d,%d): expect src(%d,%d) got (%d,%d) raw=0x%04x",
503	                (int)probe[i][0], (int)probe[i][1], (int)rx, (int)ry,
504	                (int)gx, (int)gy, (unsigned)got);
505	            }
506	          fails++;
507	        }
508	    }
509	
510	  syslog((fails == 0) ? LOG_NOTICE : LOG_WARNING,
511	    "[vrot] selftest %s: %d probes, %d fail",
512	    (fails == 0) ? "PASS" : "FAIL", (int)PROBES, (int)fails);
513	
514	  return fails == 0;
515	}
